package com.cartalaap.garage;import java.util.List;import org.springframework.security.core.Authentication;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import com.cartalaap.common.ForbiddenException;import com.cartalaap.common.NotFoundException;import com.cartalaap.user.CurrentUserService;import com.cartalaap.user.User;import com.cartalaap.user.UserRepository;
@Service public class GarageService{private final GarageVehicleRepository vehicles;private final UserRepository users;private final CurrentUserService currentUsers;public GarageService(GarageVehicleRepository vehicles,UserRepository users,CurrentUserService currentUsers){this.vehicles=vehicles;this.users=users;this.currentUsers=currentUsers;}@Transactional(readOnly=true)public List<GarageVehicleResponse>byUser(String username,Authentication auth){User owner=users.findByUsernameIgnoreCase(username).orElseThrow(()->new NotFoundException("User not found"));User current=currentUsers.optional(auth);boolean own=current!=null&&current.getId().equals(owner.getId());return vehicles.findByOwner_UsernameIgnoreCaseOrderByCreatedAtDesc(username).stream().map(v->GarageVehicleResponse.from(v,own)).toList();}@Transactional public GarageVehicleResponse create(GarageVehicleRequest r,Authentication auth){User u=currentUsers.require(auth);return GarageVehicleResponse.from(vehicles.save(new GarageVehicle(u,r)),true);}@Transactional public GarageVehicleResponse update(Long id,GarageVehicleRequest r,Authentication auth){GarageVehicle v=find(id);User u=currentUsers.require(auth);owner(v,u);v.update(r);return GarageVehicleResponse.from(v,true);}@Transactional public void delete(Long id,Authentication auth){GarageVehicle v=find(id);owner(v,currentUsers.require(auth));vehicles.delete(v);}private GarageVehicle find(Long id){return vehicles.findDetailedById(id).orElseThrow(()->new NotFoundException("Vehicle not found"));}private void owner(GarageVehicle v,User u){if(!v.getOwner().getId().equals(u.getId()))throw new ForbiddenException("You can only change vehicles in your own garage");}}
